mapper.update:
update ai_billing_settlement_task
set status = case when retry_count + 1 >= #{maxRetries}
                  then 'failed' else 'pending' end,
    available_time = case when retry_count + 1 >= #{maxRetries}
                          then available_time else #{availableTime} end,
    retry_count = retry_count + 1,
    claim_token = null,
    claim_expire_time = null,
    error_message = #{errorMessage},
    update_time = sysdate(3)
where task_id = #{taskId}
  and status = 'claimed'
  and claim_token = #{claimToken}
